// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Count calls to caddress via a proxy that tracks external calls
    // We deploy a simple counter contract that the C will call

    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Deploy a proxy contract that records the number of times it receives a call
        CallCounter counter = new CallCounter();
        // Use the counter's address as the caddress parameter
        c.transfer(from, address(counter), _tos, v);
        // The reference C should have called counter _tos.length times
        assertTrue(counter.callCount() == _tos.length);
    }
}

contract CallCounter {
    uint256 public callCount;

    // Fallback to count incoming calls
    fallback() external payable {
        callCount++;
    }

    receive() external payable {
        callCount++;
    }
}

